import io
import zipfile
from flask import Flask, request, Response

app = Flask(__name__)


@app.route("/convert", methods=["POST"])
def convert():
    if "file" not in request.files:
        return Response("Missing file field", status=400, mimetype="text/plain")

    uploaded = request.files["file"]
    if uploaded.filename == "":
        return Response("Empty filename", status=400, mimetype="text/plain")

    data = uploaded.read()
    if not data:
        return Response("Empty file", status=400, mimetype="text/plain")

    try:
        zf = zipfile.ZipFile(io.BytesIO(data))
    except zipfile.BadZipFile:
        return Response("Invalid zip file", status=400, mimetype="text/plain")

    parts = []
    try:
        for info in zf.infolist():
            if info.is_dir():
                continue
            try:
                raw = zf.read(info)
            except Exception:
                continue
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                try:
                    text = raw.decode("latin-1")
                except Exception:
                    continue
            parts.append(text)
    finally:
        zf.close()

    result = "\n".join(parts)
    return Response(result, status=200, mimetype="text/plain")


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
